/* Fixed targets and exact frame-time analysis, independent of display snapshots. */
let fixedPins=[],selectedPin='',frameVideos=[],selectedVideo='',rawPositions={},analysisRevision=0,analysisCache=null,cursorTime=null,pinLayer=null,pinLine=null,addingPin=false,pinRangeStart=null,pinRangeEnd=null,baseLayers={},baseLayerKey='offline';
const pinEl=id=>document.getElementById(id);
function setBaseLayer(key){if(!map||!baseLayers[key])return;for(let layer of Object.values(baseLayers))if(map.hasLayer(layer))map.removeLayer(layer);baseLayers[key].addTo(map);baseLayerKey=key}
function setupFusionMap(){const attribution='圖資 © <a href="https://maps.nlsc.gov.tw/" target="_blank" rel="noopener">內政部國土測繪中心</a>';baseLayers.offline=L.layerGroup();baseLayers.emap=L.tileLayer('https://wmts.nlsc.gov.tw/wmts/EMAP/default/GoogleMapsCompatible/{z}/{y}/{x}',{maxZoom:19,attribution});baseLayers.photo=L.tileLayer('https://wmts.nlsc.gov.tw/wmts/PHOTO2/default/GoogleMapsCompatible/{z}/{y}/{x}',{maxZoom:19,attribution});baseLayers.street=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri',maxZoom:19});baseLayers.satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri',maxZoom:19});for(let [key,layer]of Object.entries(baseLayers)){layer.on('tileerror',()=>{if(map.hasLayer(layer))pinEl('mapStatus').textContent='底圖暫時無法載入，可切換其他底圖；分析資料仍可使用。'});layer.on('tileload',()=>{if(map.hasLayer(layer))pinEl('mapStatus').textContent=''})}setBaseLayer(baseLayerKey);L.control.layers({'離線航跡（無底圖）':baseLayers.offline,'NLSC 電子地圖':baseLayers.emap,'NLSC 正射影像':baseLayers.photo,'Esri 街道圖':baseLayers.street,'Esri 衛星影像':baseLayers.satellite}).addTo(map);map.on('baselayerchange',e=>{baseLayerKey=Object.keys(baseLayers).find(k=>baseLayers[k]===e.layer)||'offline'});L.control.scale({imperial:false}).addTo(map);pinLayer=L.layerGroup().addTo(map);pinLine=L.layerGroup().addTo(map);map.on('click',e=>{if(!addingPin)return;createPin(e.latlng.lat,e.latlng.lng);setAddingPin(false)});drawPins()}
function setAddingPin(v){addingPin=v;pinEl('addPin').textContent=v?'取消放置（請點地圖）':'＋ 點地圖放圖釘';pinEl('addPin').classList.toggle('active',v);if(map)map.getContainer().style.cursor=v?'crosshair':'';if(v)pinEl('follow').checked=false}
function createPin(lat,lon){let p={id:globalThis.crypto?.randomUUID?.()||'pin-'+Date.now(),name:'固定目標 '+(fixedPins.length+1),lat,lon};fixedPins.push(p);selectedPin=p.id;pinEl('chartMode').value='pinDistance';changedPins();return p}
function pinSelected(){return fixedPins.find(p=>p.id===selectedPin)||null}
function videoSelected(){return frameVideos.find(v=>v.id===selectedVideo)||null}
function changedPins(){analysisRevision++;analysisCache=null;fillPinList();drawPins();fillPinEditor();if(data.length)render()}
function fillPinList(){let select=pinEl('pinSelect');select.replaceChildren();if(!fixedPins.length)select.append(new Option('尚未放置圖釘',''));for(let p of fixedPins)select.append(new Option(p.name,p.id));select.value=selectedPin}
function fillPinEditor(){let p=pinSelected();pinEl('pinName').value=p?.name||'';pinEl('pinLat').value=p?String(p.lat):'';pinEl('pinLon').value=p?String(p.lon):'';pinEl('deletePin').disabled=!p}
function drawPins(){if(!pinLayer)return;pinLayer.clearLayers();for(let p of fixedPins){let mark=L.marker([p.lat,p.lon],{draggable:true,icon:L.divIcon({className:'fixed-pin'+(p.id===selectedPin?' chosen':''),html:'<span>📍</span>',iconSize:[26,32],iconAnchor:[13,30]}),bubblingMouseEvents:false}).addTo(pinLayer).bindTooltip(document.createTextNode(p.name));mark.on('click',()=>{selectedPin=p.id;changedPins()});mark.on('dragend',()=>{let x=mark.getLatLng();p.lat=x.lat;p.lon=((x.lng+180)%360+360)%360-180;selectedPin=p.id;changedPins()})}}
function framePositionRows(){return rawPositions[sourceId()]||[]}
function analysisGap(){let n=Number(pinEl('analysisGap').value);return Number.isFinite(n)&&n>0&&n<=60?n:2}
function analysisData(){let v=videoSelected(),p=pinSelected();if(!v||!p)return [];let key=[analysisRevision,v.id,p.id,sourceId(),analysisGap()].join('|');if(analysisCache?.key===key)return analysisCache.rows;let rows=FusionCore.analyze(v,p,framePositionRows(),analysisGap());analysisCache={key,rows};return rows}
function setFusionData(videos,positions=null){let saved=pendingSettings?.fusion;frameVideos=videos.map(v=>{let old=saved?.videos?.find(x=>x.id===v.id)||frameVideos.find(x=>x.id===v.id);return {...v,...(old?{label:old.label,group:old.group,camera:old.camera,segment:old.segment}:{}),frames:v.frames}});if(positions)rawPositions=positions;if(!frameVideos.some(v=>v.id===selectedVideo))selectedVideo=saved?.selectedVideo||frameVideos[0]?.id||'';if(!frameVideos.some(v=>v.id===selectedVideo))selectedVideo=frameVideos[0]?.id||'';analysisRevision++;analysisCache=null;cursorTime=null;fillVideos();render()}
function fillVideos(){if(!VideoPlayback.active())VideoPlayback.unbind();let select=pinEl('videoSelect');select.replaceChildren();select.append(new Option('選擇 frame–UTC 配對表',''));for(let v of frameVideos)select.append(new Option(`${v.group?v.group+'° / ':''}${v.label}`,v.id));select.value=selectedVideo;VideoPlayback.fillTables();fillVideoEditor()}
function fillVideoEditor(){let v=videoSelected();for(let [id,key]of [['videoLabel','label'],['videoGroup','group'],['videoCamera','camera'],['videoSegment','segment']])pinEl(id).value=v?.[key]||'';pinEl('frameJump').min=v?.frames[0]?.frame??0;pinEl('frameJump').max=v?.frames.at(-1)?.frame??0}
function currentReplaySample(time=cursorTime){if(time===null)return data[index];let i=FusionCore.lower(data,time,s=>Date.parse(s.utc)/1000),base=i>=0?data[i]:null,s={...(base||{}),utc:new Date(time*1000).toISOString(),replayTime:time,pts:time-Date.parse(data[0].utc)/1000,frame:null,sources:{},targets:[],quality:{assignment:'sensor'},clock:{}};for(let src of Object.keys(rawPositions)){let p=FusionCore.position(rawPositions[src],time,analysisGap()),m=base?.sources?.[src]?.motion,dt=base?time-Date.parse(base.utc)/1000:Infinity;s.sources[src]={position:p,motion:m&&m.age+dt<=2?{...m,age:m.age+dt}:null}}if(base){let dt=time-Date.parse(base.utc)/1000;s.targets=(base.targets||[]).map(row=>{let out=row.slice();out[5]+=dt;return out}).filter(row=>row[5]<=30)}for(let key of ['heading','wind','apparentWind','variation']){let x=base?.[key],dt=base?time-Date.parse(base.utc)/1000:Infinity;s[key]=x&&Number.isFinite(x.age)&&x.age+dt<=(key==='wind'||key==='apparentWind'?5:2)?{...x,age:x.age+dt}:null}let p=s.sources[sourceId()]?.position;s.lat=p?.lat??null;s.lon=p?.lon??null;return s}
function seekFrame(f){if(f&&AnalysisTools.inside(f.t)&&!VideoPlayback.seek(f))moveReplayToFrame(f)}
function moveReplayToFrame(f){if(!f||!data.length||!AnalysisTools.inside(f.t))return;playing=false;pinEl('play').textContent='▶ 播放';cursorTime=f.t;index=Math.max(0,FusionCore.lower(data,f.t,s=>Date.parse(s.utc)/1000));acc=0;render()}
function selectedFrame(t){return FusionCore.nearestFrame(videoSelected()?.frames,t)}
function renderFusion(s){if(!pinEl('frameClock'))return;let pinMode=pinEl('chartMode').value==='pinDistance';pinEl('export').textContent=pinMode?'匯出圖釘區間':'匯出 AIS 區間';pinEl('fixedTimeline').hidden=!pinMode;pinEl('curve').hidden=pinMode;pinEl('start').hidden=pinMode;pinEl('end').hidden=pinMode;let v=videoSelected(),p=pinSelected(),t=cursorTime??Date.parse(s.utc)/1000,f=selectedFrame(t),op=ownAt(s);pinEl('frameClock').textContent=v?(f?`${v.label} · frame ${f.frame} · PTS ${f.pts.toFixed(6)} s · Δt ${((f.t-t)*1000).toFixed(2)} ms`:`${v.label} · 此刻無對應影格`):'尚未選擇 frame–UTC 配對表';if(pinLine){pinLine.clearLayers();if(p&&op)L.polyline([[op.lat,op.lon],[p.lat,p.lon]],{color:'#9453b9',weight:2,dashArray:'5,5',interactive:false}).addTo(pinLine)}pinEl('pinDistance').textContent=p&&op?FusionCore.distance(op,p).toFixed(2)+' m':'—';pinEl('pinPositionNote').textContent=p?`${p.name} · 本船來源 ${sourceId()} · ${op?'有效定位':'此刻無有效定位'}`:'請先在地圖放置固定目標';
 if(pinMode)pinEl('selection').textContent=p? p.name+' · '+pinEl('pinDistance').textContent:'請新增固定圖釘';let rows=analysisData(),valid=rows.filter(r=>r.distance!==null),missing=rows.length-valid.length;pinEl('frameSummary').textContent=v?`${v.frames.length.toLocaleString()} 個影格 · ${timeLabel(v.frames[0].t)} ～ ${timeLabel(v.frames.at(-1).t)}（臺灣）\n${p?`有效距離 ${valid.length.toLocaleString()} 筆；缺定位 ${missing.toLocaleString()} 筆。`:''}${v.errors?'配對表有跳過錯誤列，請核對完整性。':''}`:'可在匯入介面加入配對表，再套用至目前航跡。';let model=v?.model;pinEl('modelSummary').textContent=model?`模型 ${model.model_type} · slope ${model.slope} · 錨點 ${model.anchor_count??'—'} · RMS ${model.residual_rms_ms??'—'} ms · ${model.absolute_utc_accuracy_verified?'絕對 UTC 已驗證':'絕對 UTC 精度尚未獨立驗證'}`:'未附時間模型；直接使用配對表 UTC，不重新配適。';pinEl('frameQuality').textContent=f?`frame ${f.frame} · ${f.assignment} · ${f.ptsEstimated?'PTS 為推估':'影片 PTS'} · 錨點來源 ${f.anchorOrigin||'—'} · 殘差 ${f.residual??'—'} ms · 距錨點 ${f.anchorDistance??'—'} s`:'此刻沒有配對影格';pinEl('pinRange').textContent=`匯出區間：${pinRangeStart===null?'未設':new Date(pinRangeStart*1000).toISOString()} ～ ${pinRangeEnd===null?'未設':new Date(pinRangeEnd*1000).toISOString()}`;pinEl('exportPinAll').disabled=!(v&&p);pinEl('exportPinRange').disabled=!(v&&p&&pinRangeStart!==null&&pinRangeEnd!==null&&pinRangeEnd>=pinRangeStart);drawPinCurve(rows,f);
}
function drawPinCurve(rows,f){rows=rows.filter(r=>AnalysisTools.inside(r.t));let c=pinEl('pinCurve'),w=c.clientWidth,h=c.clientHeight||160;if(!w)return;c.width=w*devicePixelRatio;c.height=h*devicePixelRatio;let g=c.getContext('2d');g.scale(devicePixelRatio,devicePixelRatio);g.fillStyle='#6b818c';g.font='11px system-ui';if(!rows.length){g.fillText('選擇圖釘與影片後顯示距離–frame 曲線',12,80);return}let minFrame=rows[0].frame,maxFrame=rows.at(-1).frame,max=1;for(let r of rows)if(r.distance!==null)max=Math.max(max,r.distance);let [timeStart,timeEnd]=SharedTimeline.bounds();let x=n=>44+(n-timeStart)/Math.max(.001,timeEnd-timeStart)*(w-54),y=d=>h-25-d/max*(h-47);g.strokeStyle='#d5e3e9';g.beginPath();g.moveTo(44,12);g.lineTo(44,h-25);g.lineTo(w-10,h-25);g.stroke();g.fillText(max.toFixed(0)+' m',0,12);g.fillText('0',27,h-25);g.fillText(timeLabel(timeStart).slice(11),44,h-5);g.fillText(timeLabel(timeEnd).slice(11),Math.max(44,w-70),h-5);g.strokeStyle='#9453b9';g.lineWidth=1.6;g.beginPath();let prev=null;for(let r of rows){if(r.distance===null){prev=null;continue}if(prev&&r.frame===prev.frame+1)g.lineTo(x(r.t),y(r.distance));else g.moveTo(x(r.t),y(r.distance));prev=r}g.stroke();AnalysisTools.drawExportRange(g,x,1,h-25,timeStart,timeEnd);if(f){g.strokeStyle='#e39838';g.beginPath();g.moveTo(x(f.t),14);g.lineTo(x(f.t),h-25);g.stroke()}}
function exportPin(range){let v=videoSelected(),p=pinSelected();if(!p){alert('請先選取固定圖釘。');return}if(!v){alert('請先選取 frame–UTC 配對表。');return}if(range&&(pinRangeStart===null||pinRangeEnd===null||pinRangeStart>pinRangeEnd)){alert('請設定有效的分析起點與分析終點。');return}const videos=range?AnalysisTools.clips(pinRangeStart,pinRangeEnd):[v];if(range&&!videos.some(v=>v.frames.some(f=>f.t>=pinRangeStart&&f.t<=pinRangeEnd))){alert('分析區間內沒有配對影格，請調整分析起點與終點。');return}let text=videos.map((clip,i)=>{const csv=FusionCore.exportCsv({...clip,mediaFilename:VideoPlayback.filename?.(clip.id)},p,framePositionRows(),sourceId(),analysisGap(),range?[pinRangeStart,pinRangeEnd]:null);return i?csv.slice(csv.indexOf('\r\n')+2):csv}).filter(Boolean).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='fixed_target_distance_frames.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function fusionSettings(){return {pins:fixedPins,selectedPin,selectedVideo,baseLayer:baseLayerKey,gap:analysisGap(),videos:frameVideos.map(({id,label,group,camera,segment})=>({id,label,group,camera,segment}))}}
function validateFusionSettings(v){if(v===undefined)return;if(!v||!Array.isArray(v.pins)||v.pins.length>1000||!Array.isArray(v.videos))throw Error('圖釘／影片設定格式錯誤');let ids=new Set();for(let p of v.pins){if(typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||p.name.length>100||!Number.isFinite(p.lat)||Math.abs(p.lat)>90||!Number.isFinite(p.lon)||Math.abs(p.lon)>180)throw Error('圖釘座標或識別無效');ids.add(p.id)}for(let x of v.videos)for(let k of ['id','label','group','camera','segment'])if(typeof x[k]!=='string'||x[k].length>500)throw Error('影片設定格式錯誤');if(!Number.isFinite(v.gap)||v.gap<=0||v.gap>60)throw Error('定位最大間隔無效')}
function restoreFusionSettings(v){if(!v)return;fixedPins=v.pins.map(p=>({...p}));selectedPin=v.selectedPin||fixedPins[0]?.id||'';selectedVideo=v.selectedVideo||'';pinEl('analysisGap').value=v.gap;setBaseLayer(v.baseLayer);for(let video of frameVideos){let meta=v.videos.find(x=>x.id===video.id);if(meta)Object.assign(video,meta)}fillVideos();changedPins()}
function setupPinUI(){pinEl('addPin').onclick=()=>setAddingPin(!addingPin);pinEl('pinSelect').onchange=()=>{selectedPin=pinEl('pinSelect').value;changedPins()};pinEl('savePin').onclick=()=>{try{let latText=pinEl('pinLat').value,lonText=pinEl('pinLon').value,lat=Number(latText),lon=Number(lonText),name=pinEl('pinName').value.trim();if(!latText.trim()||!lonText.trim()||!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('請輸入有效的 WGS84 緯度／經度');let p=pinSelected()||createPin(lat,lon);p.lat=lat;p.lon=lon;p.name=(name||p.name).slice(0,100);changedPins();pinEl('pinMessage').textContent='圖釘已更新。'}catch(e){pinEl('pinMessage').textContent=e.message}};pinEl('deletePin').onclick=()=>{fixedPins=fixedPins.filter(p=>p.id!==selectedPin);selectedPin=fixedPins[0]?.id||'';changedPins()};pinEl('videoSelect').onchange=()=>{VideoPlayback.unbind();selectedVideo=pinEl('videoSelect').value;VideoPlayback.fillTables();cursorTime=null;pinRangeStart=pinRangeEnd=null;fillVideoEditor();render()};pinEl('saveVideoMeta').onclick=()=>{let v=videoSelected();if(!v)return;for(let [id,key]of [['videoLabel','label'],['videoGroup','group'],['videoCamera','camera'],['videoSegment','segment']])v[key]=pinEl(id).value.trim().slice(0,500);if(!v.label)v.label=v.path;fillVideos();render()};pinEl('analysisGap').oninput=()=>{analysisCache=null;render()};pinEl('jumpFrame').onclick=()=>{let v=videoSelected(),n=Number(pinEl('frameJump').value),f=v?.frames.find(f=>f.frame===n);if(f){pinEl('pinMessage').textContent='';seekFrame(f)}else pinEl('pinMessage').textContent='該影格不在選定配對表中。'};pinEl('pinCurve').onclick=e=>{let v=videoSelected();if(!v)return;let t=SharedTimeline.timeAtFraction((e.offsetX-44)/(e.currentTarget.clientWidth-54)),f=FusionCore.nearestFrame(v.frames,t);if(f)seekFrame(f);else SharedTimeline.seekUtc(t)};pinEl('pinStart').onclick=()=>{pinRangeStart=SharedTimeline.current();render()};pinEl('pinEnd').onclick=()=>{pinRangeEnd=SharedTimeline.current();render()};pinEl('exportPinAll').onclick=()=>exportPin(false);pinEl('exportPinRange').onclick=()=>exportPin(true);fillPinList();fillPinEditor();fillVideos()}
